export interface ParsedCriterionVerdict extends CriterionVerdict {
  ordinal: number;
  hasExplicitId: boolean;
  stdout: string | null;
}

export type VerificationOutcome =
  /** Verifier ran and explicitly approved the change. */
  | { kind: "verified" }
  /** Verifier ran and explicitly rejected the change with feedback. */
  | { kind: "rejected"; feedback: string }
  /** Verifier ran but produced no parseable verdict tag. Treated like a rejection by orchestration today, but distinguishable for diagnostics. */
  | { kind: "inconclusive"; reason: string }
  /** Verifier itself failed to execute (CLI error, network, etc). Orchestration currently fails open on this; surface it so it's observable. */
  | { kind: "errored"; error: string };

export interface VerificationResult {
  /** Typed verifier outcome. Use this to branch deliberately on failure modes. */
  outcome: VerificationOutcome;
  /**
   * Whether orchestration should proceed without another implement attempt.
   * Today that means an explicit PASS, and also verifier execution errors,
   * which still fail open for loop progress.
   */
  passed: boolean;
  /** When failed, actionable feedback to hand back to the implementer. */
  feedback: string;
  /** Parsed per-criterion verdict records from the verifier output. */
  criteria: ParsedCriterionVerdict[];
  raw: string;
}

function normalizeCriterionStatus(value: string | undefined): CriterionStatus {
  const normalized = value?.trim().toLowerCase();
  return normalized === "met" || normalized === "regressed" || normalized === "unmet"
    ? normalized
    : "unmet";
}

function parseCriterionAttributes(rawAttributes: string): { id?: string; status?: string } {
  const attributes: { id?: string; status?: string } = {};
  for (const match of rawAttributes.matchAll(ATTRIBUTE_PATTERN)) {
    const key = match[1]?.toLowerCase();
    const value = (match[3] ?? match[4] ?? "").trim();
    if (!value) continue;
    if (key === "id") attributes.id = value;
    if (key === "status") attributes.status = value;
  }
  return attributes;
}

function extractCriterionEvidence(rawEvidence: string): { evidenceProse: string; stdout: string | null } {
  const trimmed = rawEvidence.trim();
  const stdoutMatch = trimmed.match(FENCED_BLOCK_PATTERN);
  if (!stdoutMatch) {
    return { evidenceProse: trimmed, stdout: null };
  }

  const stdout = stdoutMatch[1] ?? "";
  const evidenceProse = trimmed.replace(stdoutMatch[0], "").trim() || "Captured command stdout.";
  return { evidenceProse, stdout };
}

function parseCriterionVerdicts(raw: string): ParsedCriterionVerdict[] {
  const criteria: ParsedCriterionVerdict[] = [];
  let ordinal = 0;

  for (const match of raw.matchAll(CRITERION_TAG_PATTERN)) {
    ordinal += 1;
    const attributes = parseCriterionAttributes(match[1] ?? "");
    const { evidenceProse, stdout } = extractCriterionEvidence(match[2] ?? "");
    const hasExplicitId = Boolean(attributes.id);
    criteria.push({
      id: attributes.id ?? `criterion-${ordinal}`,
      ordinal,
      hasExplicitId,
      status: normalizeCriterionStatus(attributes.status),
      evidenceProse,
      evidenceRef: null,
      stdout,
    });
  }

  return criteria;
}

export interface RunVerificationOptions {
  issue: Issue;
  implementerOutput: string;
  model?: string;
  cwd: string;
  promptTemplate?: string;
  git?: GitClient;
  agent?: AgentClient;
  pstackPrinciples?: string;
  onToolCall?: (name: string, args: string) => void;
  onText?: (text: string) => void;
  onUsage?: (cumulative: AgentExecutionUsage) => void;
  /** Optional label prefixed onto built-in diagnostic logs. Defaults to `#<issue id>`. */
  phaseLabel?: string;
  /** Prompt artifact recorder for capturing verify prompts before execution. */
  promptRecorder?: PromptArtifactRecorder;
  /** Client kind for manifest metadata. */
  clientKind?: PromptClientKind;
  /** Attempt number for manifest metadata. */
  attempt?: number;
  /** Per-criterion verdicts from the previous attempt. When supplied, the verifier prompt receives an anchor block so it re-confirms met criteria cheaply and focuses on unmet ones while still checking every criterion for regressions. */
  priorCriteria?: readonly CriterionVerdict[];
  /** Rendered live-steering context sections to inject into the verifier prompt. Replaces the {validation_context_block} placeholder in verify.md. When absent the placeholder is removed cleanly. */
  validationContextBlock?: string;
  /** Base commit the task worktree branched from. When provided, latestChanges uses baseRef..HEAD instead of the misleading HEAD~1..HEAD fallback. */
  baseRef?: string;
  /** Callback to record usage ledger entries. Must not throw after execution returns. */
  recordUsage?: (entry: {
    phase: "verify";
    issueId: Issue["id"];
    attempt?: number;
    client: PromptClientKind;
    model?: string;
    success: boolean;
    error?: string;
    usage?: AgentExecutionUsage;
  }) => void;
}

function formatPriorVerdictBlock(criteria: readonly CriterionVerdict[]): string {
  if (criteria.length === 0) return "";
  const blocks = criteria
    .map((c) => `<criterion id="${c.id}" status="${c.status}">${c.evidenceProse}</criterion>`)
    .join("\n");
  return [
    "## Prior verification record",
    "",
    "The previous attempt produced these per-criterion verdicts. Re-confirm every criterion:",
    "- Previously `met`: verify the evidence still holds; if it no longer holds, emit `status=\"regressed\"`.",
    "- Previously `unmet`: judge fresh.",
    "- Check every criterion for regressions even when it was `met` before.",
    "",
    "<prior_verdicts>",
    blocks,
    "</prior_verdicts>",
  ].join("\n");
}

/**
