    .replace(/\{issue_body\}/g, issue.body ?? "")
    .replace(/\{implementer_output\}/g, implementerOutput.slice(-8000))
    .replace(/\{git_diff\}/g, changes.slice(0, 60000))
    .replace(/\{pstack_principles\}/g, pstackPrinciples ?? "")
    .replace(/\{prior_verdicts_block\}/g, formatPriorVerdictBlock(options.priorCriteria ?? []))
    .replace(/\{validation_context_block\}/g, options.validationContextBlock ?? "");

