  /**
   * Record a task phase transition (write-then-emit).
   *
   * The internal tracker write happens first; the `taskPhaseChanged` fact
   * is emitted only after that write returns successfully. If the write
   * throws, no event is emitted.
   */
  recordTaskPhase(
    issueId: IssueId,
    phase: TaskPhase,
    meta?: TaskMeta,
  ): void {
    this.assertActive();
    const before = this.readTaskPhase(issueId);
    if (meta) {
      this.tracker.update((state) => this.applyMeta(state, issueId, meta));
    }
    this.tracker.update((state) => this.applyPhase(state, issueId, phase));
    this.emit({
      kind: "taskPhaseChanged",
      issueId,
      from: before,
      to: phase,
      meta,
    });
  }

  /**
