      }
      return updatedState;
    }

    case "taskMetaChanged": {
      const workerProjection = applyTaskMetaToWorkerProjection(state, event.issueId, event.meta);
      return workerProjection === null ? state : { ...state, ...workerProjection };
    }

    case "usageRecorded": {
      const workerProjection = applyUsageRecordedToWorkerProjection(state, event.entry, at);
      return { ...state, ...workerProjection };
    }

    case "streamingUsage": {
      const workerProjection = applyStreamingUsageToWorkerProjection(state, event.issueId, event.usage);
      return workerProjection === null ? state : { ...state, ...workerProjection };
    }

    case "runFinished":
