export async function loadDevelopmentPrinciples(cwd: string): Promise<string> {
  const dirPath = join(cwd, ".github", "ai");
  const filePath = join(dirPath, "development-principles.md");

  try {
    if (existsSync(filePath)) {
      return await readFile(filePath, "utf8");
    }
    await mkdir(dirPath, { recursive: true });
    await writeFile(filePath, BASELINE_PRINCIPLES, "utf8");
    return BASELINE_PRINCIPLES;
  } catch (err) {
    console.warn(`Warning: Could not read or create development principles file: ${(err as Error).message}`);
    return "";
  }
}

