  update(updater: (state: RunSnapshot) => RunSnapshot): RunSnapshot {
    const current = this.read();
    if (!current) {
      throw new Error("Cannot update: no active tracker state found");
    }
    const next = updater(current);
    next.revision = current.revision + 1;
    this.atomicWrite(next);
    return next;
  }

  updateHeartbeat(): RunSnapshot {
    return this.update((s) => ({
      ...s,
      owner: { ...s.owner, heartbeatAt: new Date().toISOString() },
    }));
  }


